'use client';

import { formatRecipeDuration } from '@/lib/recipe-duration';
import { getStepTimerMinutes, maxStepTimerMinutes, stepTimerIssue } from '@/lib/step-timer-policy';
import { MediaImage } from '@/components/MediaImage';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useCallback, useEffect, useRef, useState } from 'react';
import { AlertCircle, ArrowDown, ArrowLeft, ArrowUp, Check, CheckCircle2, ChevronRight, Clock3, Copy, Download, Eye, History, ImagePlus, LoaderCircle, Plus, RotateCcw, Save, Sparkles, Sprout, Trash2, Utensils } from 'lucide-react';
import { categories, type Ingredient, type IngredientUnit, type Locale, type RecipeStep } from '@/lib/recipes';
import { inspectRecipeDiet, recipeDiets } from '@/lib/recipe-diet';
import { reviewKeys, reviewLabels, type EditorialAction, type EditorialContent, type EditorialRecord, type RecipeSummary, type ReviewKey } from '@/lib/editorial-types';
import type { MediaTile } from '@/lib/recipe-media';
import { RecipePhoto } from '@/components/RecipePhoto';
import { SubstitutionEditor } from './SubstitutionEditor';
import { HeroPresentationFields } from './HeroPresentationFields';
import { RecipeSeoFields } from './RecipeSeoFields';
import { DeleteRecipeDialog } from './DeleteRecipeDialog';

type Tab = 'content' | 'ingredients' | 'steps' | 'photos' | 'substitutions' | 'sources' | 'seo' | 'history';
type SaveState = 'saved' | 'dirty' | 'saving' | 'error' | 'conflict';
const tabs: { id: Tab; label: string }[] = [{ id: 'content', label: 'Treść' }, { id: 'ingredients', label: 'Składniki' }, { id: 'steps', label: 'Przygotowanie' }, { id: 'photos', label: 'Zdjęcia' }, { id: 'substitutions', label: 'Zamienniki' }, { id: 'seo', label: 'SEO i kolekcje' }, { id: 'sources', label: 'Pochodzenie' }, { id: 'history', label: 'Historia' }];
const heroImages = [
  { src: '/images/lemon-pasta.webp', label: 'Cytrynowy makaron' }, { src: '/images/pumpkin-soup.webp', label: 'Krem z dyni' }, { src: '/images/spinach-pierogi.webp', label: 'Pierogi' },
  { src: '/images/ricotta-pancakes.webp', label: 'Placuszki' }, { src: '/images/apple-cake.webp', label: 'Ciasto jabłkowe' }, { src: '/images/beetroot-salad.webp', label: 'Sałatka z burakiem' },
];
const ingredientPhotoEnglish = [['Pasta', 'Butter', 'Cream', 'Hard cheese', 'Lemon', 'Basil', 'Salt', 'Pepper', 'Water', 'Pumpkin', 'Onion', 'Garlic'], ['Ginger', 'Olive oil', 'Stock', 'Coconut milk', 'Pumpkin seeds', 'Flour', 'Spinach', 'Ricotta', 'Nutmeg', 'Sage', 'Eggs', 'Milk'], ['Sugar', 'Baking powder', 'Berries', 'Honey', 'Apples', 'Cinnamon', 'Icing sugar', 'Beetroot', 'Rocket', 'Feta', 'Walnuts', 'Vinegar']];
const ingredientPhotoLabels = [['Makaron', 'Masło', 'Śmietanka', 'Ser twardy', 'Cytryna', 'Bazylia', 'Sól', 'Pieprz', 'Woda', 'Dynia', 'Cebula', 'Czosnek'], ['Imbir', 'Oliwa', 'Bulion', 'Mleczko kokosowe', 'Pestki dyni', 'Mąka', 'Szpinak', 'Ricotta', 'Gałka muszkatołowa', 'Szałwia', 'Jajka', 'Mleko'], ['Cukier', 'Proszek do pieczenia', 'Owoce leśne', 'Miód', 'Jabłka', 'Cynamon', 'Cukier puder', 'Burak', 'Rukola', 'Feta', 'Orzechy włoskie', 'Ocet']];
const stepAtlases = [{ id: 'lemon-pasta', label: 'Makaron', count: 5, aspectRatio: 1.5 }, { id: 'pumpkin-soup', label: 'Zupa', count: 5, aspectRatio: 1.5 }, { id: 'spinach-pierogi', label: 'Pierogi', count: 6, aspectRatio: 2.25 }, { id: 'ricotta-pancakes', label: 'Placuszki', count: 5, aspectRatio: 2.25 }, { id: 'apple-cake', label: 'Ciasto', count: 6, aspectRatio: 1.5 }, { id: 'beetroot-salad', label: 'Sałatka', count: 4, aspectRatio: 2.25 }];
const date = (value: string) => new Intl.DateTimeFormat('pl-PL', { timeZone: 'Europe/Warsaw', dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value));
const newId = (prefix: string) => `${prefix}-${crypto.randomUUID().slice(0, 8)}`;
const photoDescription = (value: string) => value.replace(/^(?:Ilustracja AI|AI illustration):\s*/i, '');
const revisionReason = (value: string) => value === 'Zastosowanie propozycji treści AI' ? 'Zastosowanie propozycji treści' : value;
// PostgreSQL jsonb may return object keys in a different order than an edited draft.
function fingerprint(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(fingerprint).join(',')}]`;
  if (value && typeof value === 'object') return `{${Object.entries(value).filter(([, item]) => item !== undefined).sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => `${JSON.stringify(key)}:${fingerprint(item)}`).join(',')}}`;
  return JSON.stringify(value) ?? 'null';
}

function Field({ label, children, hint }: { label: string; children: React.ReactNode; hint?: string }) {
  return <label className="admin-field">{label}{children}{hint && <small>{hint}</small>}</label>;
}

export function RecipeEditor({ initialRecipe, recipes = [] }: { initialRecipe: EditorialRecord; recipes?: RecipeSummary[] }) {
  const router = useRouter();
  const [record, setRecord] = useState(initialRecipe);
  const [content, setContent] = useState(initialRecipe.content);
  const [locale, setLocale] = useState<Locale>('pl');
  const [tab, setTab] = useState<Tab>('content');
  const [saveState, setSaveState] = useState<SaveState>('saved');
  const [error, setError] = useState('');
  const [timerErrors, setTimerErrors] = useState<Record<string, string>>({});
  const [notice, setNotice] = useState('');
  const [latest, setLatest] = useState<EditorialRecord | null>(null);
  const [actionBusy, setActionBusy] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleteError, setDeleteError] = useState('');
  const [mediaTarget, setMediaTarget] = useState<{ type: 'ingredients' | 'steps'; id: string } | null>(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [recovery, setRecovery] = useState<{ content: EditorialContent; revision: number } | null>(null);
  const contentRef = useRef(content);
  const recordRef = useRef(record);
  const persisted = useRef(fingerprint(initialRecipe.content));
  const pendingSave = useRef<Promise<boolean> | null>(null);
  const conflictRef = useRef<EditorialRecord | null>(null);
  const busyRef = useRef(false);
  const modalRef = useRef<HTMLDialogElement>(null);
  const stepTextareas = useRef<Record<string, HTMLTextAreaElement | null>>({});
  const storageKey = `jesie-editor:${initialRecipe.id}`;
  const endpoint = `/api/admin/recipes/${encodeURIComponent(initialRecipe.id)}`;
  const recipe = content.recipe;
  const inferredDiet = inspectRecipeDiet({ ingredients: recipe.ingredients }).inferredDiet;
  const inferredDietLabel = recipeDiets.find(item => item.id === inferredDiet)?.label.pl;
  const generatedProvenance = recipe.provenance.type === 'demo_ai' || recipe.provenance.type === 'ai_draft';
  const languageLabel = locale === 'pl' ? 'PL' : 'EN · UK';
  const deleted = !!record.deletedAt;
  const readonly = record.editorialStatus === 'archived' || deleted;

  const acceptRecord = useCallback((next: EditorialRecord, replaceContent: boolean) => {
    recordRef.current = next; setRecord(next); persisted.current = fingerprint(next.content);
    if (replaceContent) { contentRef.current = next.content; setContent(next.content); }
  }, []);

  const save = useCallback(async (): Promise<boolean> => {
    while (pendingSave.current) await pendingSave.current;
    if (conflictRef.current) return false;
    const snapshot = contentRef.current;
    const serialized = fingerprint(snapshot);
    if (serialized === persisted.current) return true;
    if (recordRef.current.deletedAt) return false;
    setSaveState('saving'); setError('');
    const operation = (async () => {
      try {
        const response = await fetch(endpoint, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ expectedRevision: recordRef.current.revision, content: snapshot }) });
        const body = await response.json();
        if (response.status === 409 && body.latest) { conflictRef.current = body.latest; setLatest(body.latest); setSaveState('conflict'); return false; }
        if (!response.ok || !body.recipe) throw new Error(body.error || 'Nie udało się zapisać zmian.');
        acceptRecord(body.recipe, false);
        const clean = fingerprint(contentRef.current) === persisted.current;
        setSaveState(clean ? 'saved' : 'dirty');
        if (clean) { try { localStorage.removeItem(storageKey); } catch {} }
        return true;
      } catch (err) { setSaveState('error'); setError(err instanceof Error ? err.message : 'Brak połączenia. Twój szkic pozostaje w edytorze.'); return false; }
    })();
    pendingSave.current = operation;
    const result = await operation;
    pendingSave.current = null;
    return result;
  }, [acceptRecord, endpoint, storageKey]);

  const update = (mutate: (draft: EditorialContent) => void) => {
    const draft = structuredClone(contentRef.current); mutate(draft);
    contentRef.current = draft; setContent(draft); setNotice('');
    if (!conflictRef.current) setSaveState('dirty');
    try { localStorage.setItem(storageKey, JSON.stringify({ content: draft, revision: recordRef.current.revision })); } catch {}
  };

  useEffect(() => {
    if (content === initialRecipe.content || busyRef.current || conflictRef.current || readonly || deleteOpen) return;
    const timer = setTimeout(() => void save(), 950);
    return () => clearTimeout(timer);
  }, [content, initialRecipe.content, save, readonly, deleteOpen]);
  useEffect(() => {
    const handler = (event: BeforeUnloadEvent) => { if (fingerprint(contentRef.current) !== persisted.current) { event.preventDefault(); event.returnValue = ''; } };
    window.addEventListener('beforeunload', handler);
    try {
      const saved = localStorage.getItem(storageKey);
      if (saved) { const parsed = JSON.parse(saved); if (parsed.content?.recipe?.id === initialRecipe.id && fingerprint(parsed.content) !== persisted.current) queueMicrotask(() => setRecovery(parsed)); }
    } catch {}
    return () => window.removeEventListener('beforeunload', handler);
  }, [initialRecipe.id, storageKey]);
  useEffect(() => { if (mediaTarget && !modalRef.current?.open) modalRef.current?.showModal(); }, [mediaTarget]);

  const flush = useCallback(async () => {
    for (let attempt = 0; attempt < 10; attempt++) { if (!await save()) return false; if (fingerprint(contentRef.current) === persisted.current) return true; }
    setError('Zmiany nadal się zapisują. Spróbuj jeszcze raz.'); return false;
  }, [save]);
  useEffect(() => {
    const navigate = (event: MouseEvent) => {
      if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const anchor = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>('a[href]') : null;
      if (!anchor || anchor.target === '_blank' || anchor.hasAttribute('download')) return;
      const destination = new URL(anchor.href, window.location.href);
      if (destination.origin !== window.location.origin || destination.href === window.location.href || fingerprint(contentRef.current) === persisted.current) return;
      event.preventDefault(); event.stopPropagation();
      void flush().then(saved => { if (saved) router.push(`${destination.pathname}${destination.search}${destination.hash}`); });
    };
    document.addEventListener('click', navigate, true);
    return () => document.removeEventListener('click', navigate, true);
  }, [flush, router]);
  const action = async (name: EditorialAction, extra: object = {}) => {
    if (busyRef.current) return;
    busyRef.current = true; setActionBusy(true); setNotice(''); setError('');
    try {
      if (name !== 'restore_deleted' && !await flush()) return;
      const response = await fetch(`${endpoint}/actions`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: name, expectedRevision: recordRef.current.revision, ...extra }) });
      const body = await response.json();
      if (response.status === 409 && body.latest) { conflictRef.current = body.latest; setLatest(body.latest); setSaveState('conflict'); return; }
      if (!response.ok) { if (body.issues) setRecord(current => ({ ...current, issues: body.issues })); throw new Error(body.error || 'Nie udało się wykonać tej operacji.'); }
      if (name === 'duplicate' && body.id) { router.push(`/admin/recipes/${encodeURIComponent(body.id)}`); return; }
      if (!body.recipe) throw new Error('Serwis nie zwrócił potwierdzenia operacji.');
      acceptRecord(body.recipe, true); setSaveState('saved');
      const messages: Partial<Record<EditorialAction, string>> = { review: 'Szkic jest gotowy do sprawdzenia.', approve: 'Zaakceptowano bieżącą wersję przepisu.', publish: 'Przepis jest opublikowany.', unpublish: 'Przepis został wycofany z serwisu.', archive: 'Przepis przeniesiono do archiwum.', restore: 'Przywrócono przepis jako szkic.', restore_deleted: 'Przywrócono przepis z kosza jako szkic. Publikacja wymaga ponownego zatwierdzenia.' };
      setNotice(messages[name] || 'Zmiana została zapisana.');
      try {
        if (name === 'restore_deleted') {
          const saved = localStorage.getItem(storageKey);
          if (saved) { const parsed = JSON.parse(saved); if (parsed.content?.recipe?.id === initialRecipe.id && fingerprint(parsed.content) !== fingerprint(body.recipe.content)) setRecovery(parsed); }
        } else localStorage.removeItem(storageKey);
      } catch {}
      router.refresh();
    } catch (err) { setError(err instanceof Error ? err.message : 'Nie udało się połączyć z serwisem.'); }
    finally { busyRef.current = false; setActionBusy(false); }
  };
  const deleteRecipe = async () => {
    if (busyRef.current) return;
    busyRef.current = true; setActionBusy(true); setDeleteError(''); setNotice(''); setError('');
    try {
      // Finish an already submitted save, but do not require the local draft to validate.
      while (pendingSave.current) await pendingSave.current;
      if (fingerprint(contentRef.current) !== persisted.current) {
        try { localStorage.setItem(storageKey, JSON.stringify({ content: contentRef.current, revision: recordRef.current.revision })); } catch {}
      }
      const response = await fetch(endpoint, { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ expectedRevision: recordRef.current.revision }) });
      const body = await response.json();
      if (response.status === 409) {
        if (body.latest) { conflictRef.current = body.latest; setLatest(body.latest); setSaveState('conflict'); }
        throw new Error('Przepis zmienił się w międzyczasie. Zamknij okno i wczytaj aktualną wersję przed ponownym usunięciem. Twój szkic pozostaje zachowany.');
      }
      if (!response.ok || !body.recipe) throw new Error(body.error || 'Nie udało się usunąć przepisu.');
      acceptRecord(body.recipe, true); setSaveState('saved'); setDeleteOpen(false); setPreviewOpen(false);
      setNotice('Przepis przeniesiono do kosza. Możesz przywrócić go jako szkic.');
      router.refresh();
    } catch (err) { setDeleteError(err instanceof Error ? err.message : 'Nie udało się połączyć z serwisem.'); }
    finally { busyRef.current = false; setActionBusy(false); }
  };
  const setCheck = (key: ReviewKey, checked: boolean) => void action('checks', { checks: { ...recordRef.current.checks, [key]: checked } });
  const downloadDraft = () => {
    const url = URL.createObjectURL(new Blob([JSON.stringify({ revision: recordRef.current.revision, content: contentRef.current }, null, 2)], { type: 'application/json' }));
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = `jesie-${initialRecipe.id}-szkic.json`; anchor.click(); URL.revokeObjectURL(url);
  };
  const resolveConflict = async (keepLocal: boolean) => {
    const current = conflictRef.current; if (!current) return;
    acceptRecord(current, !keepLocal); conflictRef.current = null; setLatest(null); setError('');
    if (keepLocal) { setSaveState('dirty'); await save(); } else { setSaveState('saved'); try { localStorage.removeItem(storageKey); } catch {} }
  };
  const changeIngredient = (id: string, mutate: (ingredient: Ingredient) => void) => update(draft => { const item = draft.recipe.ingredients.find(ingredient => ingredient.id === id); if (item) mutate(item); });
  const changeStep = (id: string, mutate: (step: RecipeStep) => void) => update(draft => { const item = draft.recipe.steps.find(step => step.id === id); if (item) mutate(item); });
  const changeStepTimer = (id: string, input: HTMLInputElement) => {
    const current = contentRef.current.recipe.steps.find(step => step.id === id);
    if (!current) return;
    const minutes = Number(input.value);
    const candidate = { ...current, timerMinutes: minutes };
    if (input.validity.badInput || input.value !== '' && (!Number.isSafeInteger(minutes) || minutes < 1 || getStepTimerMinutes(candidate) !== minutes)) {
      setTimerErrors(errors => ({ ...errors, [id]: `Nie zmieniono minutnika. ${stepTimerIssue(candidate) ?? 'Wpisz dodatnią liczbę całkowitą minut.'}` }));
      return;
    }
    setTimerErrors(errors => ({ ...errors, [id]: '' }));
    changeStep(id, step => { if (input.value === '') delete step.timerMinutes; else step.timerMinutes = minutes; });
  };
  const move = (type: 'ingredients' | 'steps', index: number, delta: number) => update(draft => { const items = draft.recipe[type]; const target = index + delta; if (target >= 0 && target < items.length) [items[index], items[target]] = [items[target], items[index]]; });
  const chooseMedia = (media: MediaTile) => { if (!mediaTarget) return; update(draft => { draft.photos[mediaTarget.type][mediaTarget.id] = media; }); modalRef.current?.close(); setMediaTarget(null); };
  const insertIngredient = (stepId: string, ingredientId: string) => {
    if (!ingredientId) return;
    const textarea = stepTextareas.current[stepId];
    const position = textarea?.selectionStart ?? recipe.steps.find(step => step.id === stepId)?.text[locale].length ?? 0;
    const end = textarea?.selectionEnd ?? position;
    const token = `{{${ingredientId}}}`;
    changeStep(stepId, step => { step.text[locale] = `${step.text[locale].slice(0, position)}${token}${step.text[locale].slice(end)}`; });
    requestAnimationFrame(() => { textarea?.focus(); textarea?.setSelectionRange(position + token.length, position + token.length); });
  };

  return <>
    <div className="admin-save-bar"><Link href="/admin/recipes" className="admin-breadcrumb" style={{ marginBottom: 0 }} onClick={async event => { if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); if (await flush()) router.push('/admin/recipes'); }}><ArrowLeft size={17} />Przepisy</Link><div className="admin-save-state" role="status" aria-live="polite">{saveState === 'saving' ? <LoaderCircle size={18} className="admin-spinner" /> : saveState === 'saved' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}{saveState === 'saved' ? 'Wszystkie zmiany zapisane' : saveState === 'saving' ? 'Zapisuję…' : saveState === 'dirty' ? 'Niezapisane zmiany' : saveState === 'conflict' ? 'Konflikt wersji' : 'Zapis wymaga ponowienia'}<span>· Wersja {record.revision}</span></div><button type="button" className="admin-button" disabled={saveState === 'saving' || actionBusy || !!latest || readonly} onClick={() => void flush()}><Save size={17} />Zapisz</button>{!deleted && <button type="button" className="admin-button is-danger" disabled={actionBusy || !!latest} onClick={() => { setDeleteError(''); setDeleteOpen(true); }}><Trash2 size={17} />Usuń przepis</button>}</div>
    {recovery && !deleted && <div className="admin-notice admin-conflict"><AlertCircle size={20} /><div><p>W tej przeglądarce pozostał niezapisany szkic z wersji {recovery.revision}.</p><div className="admin-actions"><button type="button" className="admin-button is-secondary" onClick={() => { contentRef.current = recovery.content; setContent(recovery.content); setRecovery(null); if (recovery.revision !== recordRef.current.revision) { conflictRef.current = recordRef.current; setLatest(recordRef.current); setSaveState('conflict'); } else setSaveState('dirty'); }}>Przywróć mój szkic</button><button type="button" className="admin-button is-subtle" onClick={() => { setRecovery(null); try { localStorage.removeItem(storageKey); } catch {} }}>Usuń kopię lokalną</button></div></div></div>}
    {latest && <div className="admin-notice is-error admin-conflict" role="alert"><AlertCircle size={21} /><div><p><strong>Ktoś zapisał nowszą wersję {latest.revision}.</strong> Twój tekst pozostaje w edytorze. Wersję serwera zmienił(a) {latest.updatedBy}, {date(latest.updatedAt)}.</p><p>{latest.deletedAt ? 'Przepis trafił do kosza. Pobierz swój szkic, a następnie wczytaj wersję serwera. Przed dalszą edycją trzeba przywrócić przepis z kosza.' : 'Możesz pobrać swój szkic, wczytać wersję serwera albo świadomie zapisać całą swoją treść jako następną wersję.'}</p><details><summary>Porównaj z wersją serwera</summary><pre style={{ maxHeight: 260, overflow: 'auto', fontSize: 11, whiteSpace: 'pre-wrap' }}>{JSON.stringify(latest.content, null, 2)}</pre></details><div className="admin-actions"><button type="button" className="admin-button is-secondary" onClick={downloadDraft}><Download size={16} />Pobierz mój szkic</button><button type="button" className="admin-button is-secondary" onClick={() => void resolveConflict(false)}>Wczytaj wersję serwera</button><button type="button" className="admin-button" disabled={!!latest.deletedAt} onClick={() => void resolveConflict(true)}>Zapisz moją treść jako kolejną wersję</button></div></div></div>}
    {error && <div className="admin-notice is-error" role="alert"><AlertCircle size={18} /><span>{error}</span></div>}{notice && <div className="admin-notice is-success" role="status"><CheckCircle2 size={18} /><span>{notice}</span></div>}
    <div className="admin-editor-heading"><div><h1>{recipe.title.pl || recipe.title.en || 'Nowy przepis'}</h1><span className={`admin-tag ${deleted ? 'is-deleted' : record.editorialStatus === 'archived' ? 'is-archived' : record.editorialStatus !== 'draft' ? 'is-review' : ''}`}>{deleted ? 'Kosz' : record.editorialStatus === 'draft' ? 'Szkic' : record.editorialStatus === 'in_review' ? 'Do sprawdzenia' : record.editorialStatus === 'approved' ? 'Zaakceptowany' : 'Archiwum'}</span></div><p>{deleted ? 'Przepis jest w koszu. Przywróć go jako szkic, aby kontynuować pracę.' : 'Dopracuj przepis. Sprawdź oba języki. Opublikuj, kiedy będzie gotowy.'}</p>{!deleted && <Link href={'/admin/ai?recipe=' + encodeURIComponent(record.id)} className="admin-text-link admin-ai-editor-link"><Sparkles size={16} />Otwórz w Studio</Link>}</div>
    <div className="admin-editor-grid"><div className="admin-editor-content"><div className="admin-editor-tabs"><div role="tablist" aria-label="Sekcje przepisu">{tabs.map(item => <button type="button" role="tab" key={item.id} id={`tab-${item.id}`} aria-selected={tab === item.id} aria-controls={`panel-${item.id}`} onClick={() => setTab(item.id)}>{item.label}</button>)}</div><div className="admin-locale-tabs" aria-label="Język edycji"><button type="button" aria-pressed={locale === 'pl'} onClick={() => setLocale('pl')}>PL</button><button type="button" aria-pressed={locale === 'en'} onClick={() => setLocale('en')}>EN</button></div></div>
      <div role="tabpanel" id={`panel-${tab}`} aria-labelledby={`tab-${tab}`}><fieldset disabled={actionBusy || readonly} style={{ border: 0, margin: 0, padding: 0, minWidth: 0 }}>
        {tab === 'seo' && <RecipeSeoFields content={content} locale={locale} recipes={recipes} onChange={update} />}
        {tab === 'content' && <><section className="admin-section"><h2>Historia dania</h2><p>Edytujesz {locale === 'pl' ? 'wersję polską' : 'wersję angielską (UK)'}. Ilości i czasy są wspólne dla obu języków.</p><Field label={`Tytuł (${languageLabel})`}><input maxLength={200} value={recipe.title[locale]} onChange={event => update(draft => { draft.recipe.title[locale] = event.target.value; })} /></Field><Field label={`Krótki opis (${languageLabel})`}><textarea value={recipe.description[locale]} rows={3} onChange={event => update(draft => { draft.recipe.description[locale] = event.target.value; })} /></Field><div className="admin-field-grid"><Field label={`Adres przepisu (${languageLabel})`} hint="Małe litery, cyfry i łączniki. Zmiana adresu nie zmienia jeszcze wersji publicznej."><input value={recipe.slug[locale]} onChange={event => update(draft => { draft.recipe.slug[locale] = event.target.value; })} /></Field><Field label={`Kuchnia (${languageLabel})`}><input value={recipe.cuisine[locale]} onChange={event => update(draft => { draft.recipe.cuisine[locale] = event.target.value; })} /></Field></div></section><section className="admin-section"><h2>Porcje, czas i kategorie</h2><div className="admin-field" style={{ marginBlock: 20 }}><span>Rodzaj dania</span><span>{inferredDietLabel ?? 'Doprecyzuj składniki, aby ustalić rodzaj dania.'}</span><small>Ustalany automatycznie ze składników podstawowej wersji przepisu. Opcjonalne zamienniki nie zmieniają kategorii.</small></div><div className="admin-field-grid"><Field label="Liczba porcji (baza)"><input type="number" min="1" max="100" value={recipe.baseServings} onChange={event => update(draft => { draft.recipe.baseServings = Number(event.target.value); })} /></Field><Field label="Poziom trudności"><select value={recipe.difficulty} onChange={event => update(draft => { draft.recipe.difficulty = event.target.value as 'easy' | 'medium'; })}><option value="easy">Łatwy</option><option value="medium">Średni</option></select></Field></div><div className="admin-inline-fields" style={{ marginTop: 20 }}>{[{ id: 'active', label: 'Praca · min' }, { id: 'cooking', label: 'Gotowanie · min' }, { id: 'rest', label: 'Odpoczynek · min' }, { id: 'total', label: 'Łącznie · min' }].map(item => <Field key={item.id} label={item.label} hint={`${locale === 'pl' ? 'Wpisz liczbę minut. Podgląd:' : 'Enter minutes. Preview:'} ${formatRecipeDuration(recipe.times[item.id as keyof typeof recipe.times], locale)}`}><input type="number" min="0" max="10080" value={recipe.times[item.id as keyof typeof recipe.times]} onChange={event => update(draft => { draft.recipe.times[item.id as keyof typeof recipe.times] = Number(event.target.value); })} /></Field>)}</div><Field label="Główna kategoria"><select value={recipe.primaryCategory} onChange={event => update(draft => { draft.recipe.primaryCategory = event.target.value as typeof recipe.primaryCategory; if (!draft.recipe.categories.includes(draft.recipe.primaryCategory)) draft.recipe.categories.push(draft.recipe.primaryCategory); })}>{categories.map(category => <option key={category.id} value={category.id}>{category.label.pl}</option>)}</select></Field><div className="admin-category-grid">{categories.map(category => <label className="admin-checkbox" key={category.id}><input type="checkbox" checked={recipe.categories.includes(category.id)} disabled={recipe.primaryCategory === category.id} onChange={event => update(draft => { draft.recipe.categories = event.target.checked ? [...draft.recipe.categories, category.id] : draft.recipe.categories.filter(id => id !== category.id); })} />{category.label.pl}</label>)}</div><label className="admin-checkbox"><input type="checkbox" checked={recipe.featured} onChange={event => update(draft => { draft.recipe.featured = event.target.checked; })} />Wyróżnij przepis w serwisie</label></section><section className="admin-section"><h2>Przydatne przy gotowaniu</h2><Field label={`Sprzęt (${languageLabel})`} hint="Jeden element w każdym wierszu."><textarea value={recipe.equipment[locale].join('\n')} rows={4} onChange={event => update(draft => { draft.recipe.equipment[locale] = event.target.value.split('\n'); })} /></Field><Field label={`Wskazówki (${languageLabel})`} hint="Jedna wskazówka w każdym wierszu."><textarea value={recipe.tips[locale].join('\n')} rows={5} onChange={event => update(draft => { draft.recipe.tips[locale] = event.target.value.split('\n'); })} /></Field><Field label={`Przechowywanie (${languageLabel})`}><textarea value={recipe.storage[locale]} rows={3} onChange={event => update(draft => { draft.recipe.storage[locale] = event.target.value; })} /></Field><Field label={`Uwaga o zmianie porcji (${languageLabel})`}><textarea value={recipe.scalingNote?.[locale] || ''} rows={2} onChange={event => update(draft => { draft.recipe.scalingNote ??= { pl: '', en: '' }; draft.recipe.scalingNote[locale] = event.target.value; })} /></Field></section><section className="admin-section"><h2>Tagi dietetyczne</h2><p>Każda deklaracja wymaga sprawdzenia składników i ich etykiet.</p>{recipe.dietaryTags.map((tagItem, index) => <div className="admin-inline-fields" key={tagItem.id}><Field label={`Nazwa tagu (${languageLabel})`}><input value={tagItem.label[locale]} onChange={event => update(draft => { draft.recipe.dietaryTags[index].label[locale] = event.target.value; })} /></Field><span className="admin-chip">Do sprawdzenia</span><button type="button" className="admin-icon-button" aria-label={`Usuń tag ${tagItem.label.pl}`} onClick={() => update(draft => { draft.recipe.dietaryTags.splice(index, 1); })}><Trash2 size={17} /></button></div>)}<button type="button" className="admin-button is-secondary admin-wide-add" onClick={() => update(draft => { draft.recipe.dietaryTags.push({ id: newId('diet'), label: { pl: '', en: '' }, status: 'to_review' }); })}><Plus size={17} />Dodaj tag</button></section></>}
        {tab === 'ingredients' && <section className="admin-section"><div className="admin-page-heading" style={{ marginBottom: 18 }}><div><h2>Składniki i proporcje</h2><p>Jedna baza ilości dla obu języków.</p></div><Field label="Liczba porcji (baza)"><input type="number" min="1" max="100" value={recipe.baseServings} onChange={event => update(draft => { draft.recipe.baseServings = Number(event.target.value); })} /></Field></div><div className="admin-notice"><AlertCircle size={17} /><span>Ilości są wspólne. Przełączając PL / EN, zmieniasz nazwy, grupy i uwagi.</span></div>{recipe.ingredients.map((ingredient, index) => <div className="admin-ingredient-editor" key={ingredient.id}><button type="button" className="admin-icon-button" onClick={() => setMediaTarget({ type: 'ingredients', id: ingredient.id })} aria-label={`Zmień zdjęcie: ${ingredient.name.pl || `składnik ${index + 1}`}`} style={{ padding: 0 }}>{content.photos.ingredients[ingredient.id] ? <RecipePhoto media={content.photos.ingredients[ingredient.id]} locale={locale} className="ingredient-thumb" sizes="62px" legacySizes="320px" maximumWidth={320} decorative /> : <ImagePlus size={28} strokeWidth={1.4} />}</button><Field label={`Nazwa (${languageLabel})`}><input value={ingredient.name[locale]} onChange={event => changeIngredient(ingredient.id, item => { item.name[locale] = event.target.value; })} /></Field><Field label={ingredient.amount.kind === 'range' ? 'Ilość od / do' : 'Ilość'}>{ingredient.amount.kind === 'exact' ? <input inputMode="decimal" value={ingredient.amount.value} onChange={event => changeIngredient(ingredient.id, item => { if (item.amount.kind === 'exact') item.amount.value = event.target.value.replace(',', '.'); })} /> : ingredient.amount.kind === 'range' ? <><input aria-label="Ilość minimalna" inputMode="decimal" value={ingredient.amount.min} onChange={event => changeIngredient(ingredient.id, item => { if (item.amount.kind === 'range') item.amount.min = event.target.value.replace(',', '.'); })} /><input aria-label="Ilość maksymalna" inputMode="decimal" value={ingredient.amount.max} onChange={event => changeIngredient(ingredient.id, item => { if (item.amount.kind === 'range') item.amount.max = event.target.value.replace(',', '.'); })} /></> : <input value={ingredient.amount.text[locale]} placeholder={locale === 'pl' ? 'do smaku' : 'to taste'} onChange={event => changeIngredient(ingredient.id, item => { if (item.amount.kind === 'qualitative') item.amount.text[locale] = event.target.value; })} />}</Field><Field label="Jednostka"><select disabled={ingredient.amount.kind === 'qualitative'} value={ingredient.unit || ''} onChange={event => changeIngredient(ingredient.id, item => { item.unit = (event.target.value || null) as IngredientUnit; })}><option value="">—</option><option value="g">g</option><option value="ml">ml</option><option value="count">szt.</option><option value="tsp">łyżeczka</option><option value="tbsp">łyżka</option></select></Field><button type="button" className="admin-icon-button" aria-label={`Usuń składnik ${ingredient.name.pl || index + 1}`} onClick={() => update(draft => { draft.recipe.substitutions = draft.recipe.substitutions?.filter(item => item.ingredientId !== draft.recipe.ingredients[index].id); draft.recipe.ingredients.splice(index, 1); delete draft.photos.ingredients[ingredient.id]; })}><Trash2 size={18} /></button><details className="admin-ingredient-details" style={{ display: 'block' }}><summary>Grupa, rodzaj ilości i skalowanie</summary><div className="admin-field-grid"><Field label="Rodzaj ilości"><select value={ingredient.amount.kind} onChange={event => changeIngredient(ingredient.id, item => { const kind = event.target.value; item.amount = kind === 'range' ? { kind: 'range', min: '', max: '' } : kind === 'qualitative' ? { kind: 'qualitative', text: { pl: '', en: '' } } : { kind: 'exact', value: '' }; if (kind === 'qualitative') { item.unit = null; item.scaling = 'fixed'; } })}><option value="exact">Dokładna ilość</option><option value="range">Zakres od / do</option><option value="qualitative">Opisowa (do smaku)</option></select></Field><Field label={`Nazwa (${locale === 'pl' ? 'EN' : 'PL'})`}><input value={ingredient.name[locale === 'pl' ? 'en' : 'pl']} onChange={event => changeIngredient(ingredient.id, item => { item.name[locale === 'pl' ? 'en' : 'pl'] = event.target.value; })} /></Field><Field label={`Grupa (${languageLabel})`}><input value={ingredient.group[locale]} placeholder={locale === 'pl' ? 'Na przykład: Nadzienie' : 'For example: Filling'} onChange={event => changeIngredient(ingredient.id, item => { item.group[locale] = event.target.value; })} /></Field><Field label={`Uwagi (${languageLabel})`}><input value={ingredient.note?.[locale] || ''} onChange={event => changeIngredient(ingredient.id, item => { item.note ??= { pl: '', en: '' }; item.note[locale] = event.target.value; })} /></Field></div><label className="admin-checkbox"><input type="checkbox" checked={ingredient.scaling === 'fixed'} disabled={ingredient.amount.kind === 'qualitative'} onChange={event => changeIngredient(ingredient.id, item => { item.scaling = event.target.checked ? 'fixed' : 'linear'; })} />Ilość stała przy zmianie porcji</label>{ingredient.amount.kind !== 'qualitative' && <label className="admin-checkbox"><input type="checkbox" checked={!!ingredient.amount.approximate} onChange={event => changeIngredient(ingredient.id, item => { if (item.amount.kind !== 'qualitative') item.amount.approximate = event.target.checked; })} />Ilość przybliżona (około)</label>}<div className="admin-actions"><span className="admin-subtle">Odniesienie w kroku: {'{{'}{ingredient.id}{'}}'}</span><button type="button" className="admin-icon-button" disabled={index === 0} aria-label="Przenieś składnik wyżej" onClick={() => move('ingredients', index, -1)}><ArrowUp size={17} /></button><button type="button" className="admin-icon-button" disabled={index === recipe.ingredients.length - 1} aria-label="Przenieś składnik niżej" onClick={() => move('ingredients', index, 1)}><ArrowDown size={17} /></button></div></details></div>)}<button type="button" className="admin-button is-secondary admin-wide-add" onClick={() => update(draft => { draft.recipe.ingredients.push({ id: newId('ingredient'), name: { pl: '', en: '' }, amount: { kind: 'exact', value: '' }, unit: 'g', scaling: 'linear', group: { pl: 'Składniki', en: 'Ingredients' } }); })}><Plus size={19} />Dodaj składnik</button></section>}
        {tab === 'steps' && <section className="admin-section"><h2>Gotowanie, krok po kroku</h2><p>Wstaw ilość składnika, aby zmieniała się wraz z liczbą porcji. Jego nazwę zapisz samodzielnie w zdaniu.</p>{recipe.steps.map((step, index) => <div className="admin-step-editor" key={step.id}><div className="admin-step-editor-header"><strong>Krok {index + 1}</strong><div className="admin-actions"><button type="button" className="admin-icon-button" disabled={index === 0} aria-label="Przenieś krok wyżej" onClick={() => move('steps', index, -1)}><ArrowUp size={18} /></button><button type="button" className="admin-icon-button" disabled={index === recipe.steps.length - 1} aria-label="Przenieś krok niżej" onClick={() => move('steps', index, 1)}><ArrowDown size={18} /></button><button type="button" className="admin-icon-button" aria-label={`Usuń krok ${index + 1}`} onClick={() => update(draft => { draft.recipe.steps.splice(index, 1); delete draft.photos.steps[step.id]; })}><Trash2 size={18} /></button></div></div><Field label={`Tytuł kroku (${languageLabel})`}><input value={step.title[locale]} onChange={event => changeStep(step.id, item => { item.title[locale] = event.target.value; })} /></Field><Field label={`Przygotowanie (${languageLabel})`}><textarea ref={element => { stepTextareas.current[step.id] = element; }} value={step.text[locale]} rows={5} onChange={event => changeStep(step.id, item => { item.text[locale] = event.target.value; })} /></Field><div className="admin-inline-fields" style={{ marginTop: 14 }}><Field label="Wstaw ilość składnika w miejscu kursora"><select value="" disabled={!recipe.ingredients.length} onChange={event => insertIngredient(step.id, event.target.value)}><option value="">Wybierz składnik…</option>{recipe.ingredients.map(ingredient => <option key={ingredient.id} value={ingredient.id}>{ingredient.name[locale] || ingredient.id}</option>)}</select></Field><div style={{ flex: 1, minWidth: 160 }}><Field label="Minutnik · min"><input type="number" min="1" max={maxStepTimerMinutes} step="1" value={step.timerMinutes ?? ''} aria-describedby={`step-timer-help-${step.id}`} onChange={event => changeStepTimer(step.id, event.currentTarget)} /><small id={`step-timer-help-${step.id}`}>Opcjonalnie, do {formatRecipeDuration(maxStepTimerMinutes, 'pl')}. Oczekiwanie przez noc lub cały dzień zapisz w opisie i czasie przepisu. Puste pole usuwa minutnik.</small></Field>{timerErrors[step.id] && <p className="admin-inline-error" role="alert">{timerErrors[step.id]}</p>}{step.timerMinutes !== undefined && getStepTimerMinutes(step) === null && <p className="admin-inline-error">{stepTimerIssue(step)} Ten zapisany minutnik nie pojawi się w przepisie. Możesz usunąć go poniżej; opis i pełny czas pozostaną.</p>}{step.timerMinutes !== undefined && <button type="button" className="admin-button is-subtle" onClick={() => { setTimerErrors(errors => ({ ...errors, [step.id]: '' })); changeStep(step.id, item => { delete item.timerMinutes; }); }}>Usuń minutnik</button>}</div></div></div>)}<button type="button" className="admin-button is-secondary admin-wide-add" onClick={() => update(draft => { draft.recipe.steps.push({ id: newId('step'), title: { pl: '', en: '' }, text: { pl: '', en: '' } }); })}><Plus size={19} />Dodaj krok</button></section>}
        {tab === 'photos' && <><section className="admin-section"><HeroPresentationFields recipe={recipe} onChange={presentation => update(draft => { draft.recipe.heroPresentation = presentation; })} disabled={actionBusy || readonly || !!latest} /></section><section className="admin-section"><h2>Obraz przepisu</h2><p>Wybierz zdjęcie z biblioteki i opisz widoczne danie w obu językach.</p><div className="admin-media-grid">{heroImages.map(photo => <button type="button" className="admin-media-choice" key={photo.src} aria-pressed={recipe.image === photo.src} onClick={() => update(draft => { draft.recipe.image = photo.src; draft.recipe.imageAlt = { pl: '', en: '' }; })}><MediaImage src={photo.src} alt={photo.label} width={210} height={150} sizes="210px" maximumWidth={480} /><span>{photo.label}</span></button>)}</div><Field label={`Opis alternatywny zdjęcia (${languageLabel})`} hint="Opisz widoczne danie, jego składniki i najważniejszy detal."><input value={photoDescription(recipe.imageAlt[locale])} onChange={event => update(draft => { draft.recipe.imageAlt[locale] = event.target.value; })} /></Field><button type="button" className="admin-button is-subtle" onClick={() => update(draft => { draft.recipe.image = ''; draft.recipe.imageAlt = { pl: '', en: '' }; })}>Usuń zdjęcie dania</button></section><section className="admin-section"><h2>Zdjęcia składników</h2><p>Powiązania dotyczą konkretnych składników i pozostają przy nich po zmianie kolejności.</p>{recipe.ingredients.map((ingredient, index) => <div className="admin-step-editor" key={ingredient.id}><div className="admin-step-editor-header">{content.photos.ingredients[ingredient.id] ? <RecipePhoto media={content.photos.ingredients[ingredient.id]} locale={locale} className="ingredient-thumb" sizes="62px" legacySizes="320px" maximumWidth={320} /> : <ImagePlus size={25} />}<span>{ingredient.name[locale] || `Składnik ${index + 1}`}</span><div className="admin-actions"><button type="button" className="admin-button is-secondary" onClick={() => setMediaTarget({ type: 'ingredients', id: ingredient.id })}>{content.photos.ingredients[ingredient.id] ? 'Zmień' : 'Wybierz'}</button>{content.photos.ingredients[ingredient.id] && <button type="button" className="admin-icon-button" aria-label={`Usuń zdjęcie: ${ingredient.name[locale]}`} onClick={() => update(draft => { delete draft.photos.ingredients[ingredient.id]; })}><Trash2 size={16} /></button>}</div></div>{content.photos.ingredients[ingredient.id] && <Field label={`Opis zdjęcia (${languageLabel})`}><input value={photoDescription(content.photos.ingredients[ingredient.id].alt[locale])} onChange={event => update(draft => { draft.photos.ingredients[ingredient.id].alt[locale] = event.target.value; })} /></Field>}</div>)}</section><section className="admin-section"><h2>Zdjęcia przygotowania</h2><p>Wybierz kadr, który odpowiada rzeczywistej czynności. Sprawdź opis wizualnej wskazówki w obu językach.</p>{recipe.steps.map((step, index) => <div className="admin-step-editor" key={step.id}><div className="admin-step-editor-header">{content.photos.steps[step.id] ? <RecipePhoto media={content.photos.steps[step.id]} locale={locale} className="ingredient-thumb" sizes="62px" legacySizes="320px" maximumWidth={320} /> : <ImagePlus size={25} />}<span>Krok {index + 1}: {step.title[locale]}</span><div className="admin-actions"><button type="button" className="admin-button is-secondary" onClick={() => setMediaTarget({ type: 'steps', id: step.id })}>{content.photos.steps[step.id] ? 'Zmień' : 'Wybierz'}</button>{content.photos.steps[step.id] && <button type="button" className="admin-icon-button" aria-label={`Usuń zdjęcie kroku ${index + 1}`} onClick={() => update(draft => { delete draft.photos.steps[step.id]; })}><Trash2 size={16} /></button>}</div></div>{content.photos.steps[step.id] && <><Field label={`Opis zdjęcia (${languageLabel})`}><input value={photoDescription(content.photos.steps[step.id].alt[locale])} onChange={event => update(draft => { draft.photos.steps[step.id].alt[locale] = event.target.value; })} /></Field><Field label={`Wskazówka wizualna (${languageLabel})`}><textarea rows={2} value={content.photos.steps[step.id].caption?.[locale] || ''} onChange={event => update(draft => { draft.photos.steps[step.id].caption ??= { pl: '', en: '' }; draft.photos.steps[step.id].caption![locale] = event.target.value; })} /></Field></>}</div>)}</section></>}
        {tab === 'substitutions' && <SubstitutionEditor ingredients={recipe.ingredients} substitutions={recipe.substitutions ?? []} locale={locale} onChange={items => update(draft => { draft.recipe.substitutions = items; })} />}
        {tab === 'sources' && <><section className="admin-section"><h2>Skąd pochodzi przepis?</h2><p>Autor, oryginał i źródła to prywatne informacje redakcyjne zachowane przy szkicu.</p><Field label="Rodzaj pochodzenia"><select value={recipe.provenance.type} onChange={event => update(draft => { draft.recipe.provenance.type = event.target.value as typeof recipe.provenance.type; })}><option value="original">Własny przepis</option><option value="adapted">Adaptacja przepisu</option><option value="ai_draft">Szkic redakcyjny</option><option value="demo_ai">Kolekcja początkowa</option></select></Field><Field label="Autor / autorka"><input value={content.author} onChange={event => update(draft => { draft.author = event.target.value; })} /></Field>{!generatedProvenance && <><Field label={`Oznaczenie redakcyjne (${languageLabel})`}><input value={recipe.provenance.label[locale]} onChange={event => update(draft => { draft.recipe.provenance.label[locale] = event.target.value; })} /></Field><Field label={`Notatka redakcyjna (${languageLabel})`}><textarea value={recipe.provenance.note[locale]} rows={5} onChange={event => update(draft => { draft.recipe.provenance.note[locale] = event.target.value; })} /></Field></>}<div className="admin-notice"><AlertCircle size={18} /><span>{recipe.provenance.kitchenTested ? 'Ten przepis oznaczono jako sprawdzony w kuchni.' : 'Ten przepis nie jest oznaczony jako sprawdzony w kuchni. Sprawdź zgodność opisu z rzeczywistym pochodzeniem.'}</span></div></section><section className="admin-section"><h2>Źródła i odnośniki</h2>{content.sources.map((source, index) => <div key={source.id} className="admin-step-editor"><div className="admin-field-grid"><Field label="Nazwa źródła"><input value={source.title} onChange={event => update(draft => { draft.sources[index].title = event.target.value; })} /></Field><Field label="Adres źródła"><input type="url" value={source.url} placeholder="https://…" onChange={event => update(draft => { draft.sources[index].url = event.target.value; })} /></Field></div><button type="button" className="admin-button is-subtle" onClick={() => update(draft => { draft.sources.splice(index, 1); })}><Trash2 size={16} />Usuń źródło</button></div>)}<button type="button" className="admin-button is-secondary admin-wide-add" onClick={() => update(draft => { draft.sources.push({ id: newId('source'), title: '', url: '' }); })}><Plus size={18} />Dodaj źródło</button></section><section className="admin-section"><h2>Oryginalna treść</h2><p>Twoje notatki pozostają dostępne podczas porządkowania przepisu.</p><Field label="Oryginał"><textarea value={content.originalText} rows={12} onChange={event => update(draft => { draft.originalText = event.target.value; })} /></Field></section></>}
      </fieldset>{tab === 'history' && <section className="admin-section"><h2>Każda wersja ma swoją historię.</h2><p>Przywrócenie tworzy kolejny szkic. Wersja publiczna pozostaje dostępna do chwili osobnej publikacji lub wycofania.</p><ol className="admin-history">{record.versions.map(version => <li key={version.revision}><History size={19} /><div><strong>Wersja {version.revision}{version.revision === record.revision ? ' · bieżąca' : ''}{version.revision === record.publishedRevision ? ' · publiczna' : ''}</strong><p>{version.title}</p><p>{revisionReason(version.reason)} · {date(version.createdAt)} · {version.createdBy}</p></div><button type="button" className="admin-button is-secondary" disabled={actionBusy || !!latest || deleted || version.revision === record.revision} onClick={() => void action('restore', { version: version.revision })}><RotateCcw size={16} />Przywróć</button></li>)}</ol><button type="button" className="admin-button is-secondary admin-wide-add" onClick={downloadDraft}><Download size={17} />Pobierz bieżący szkic</button></section>}</div>
    </div><aside className="admin-editor-rail">{!deleted && <section><h2>Przed publikacją</h2><p className="admin-subtle" style={{ marginBottom: 12 }}>Akceptacja dotyczy wersji {record.revision}. Każda zmiana treści wymaga ponownego sprawdzenia.</p>{reviewKeys.map(key => <label className={`admin-review-check ${record.checks[key] ? 'is-ok' : 'is-pending'}`} key={key}><input type="checkbox" checked={record.checks[key]} disabled={actionBusy || !!latest || readonly || saveState !== 'saved'} onChange={event => setCheck(key, event.target.checked)} />{record.checks[key] ? <CheckCircle2 size={17} /> : <AlertCircle size={17} />}<span>{reviewLabels[key]}{record.checks[key] && <small>Sprawdzone w tej wersji</small>}</span></label>)}{record.issues.length > 0 && <details><summary className="admin-subtle">Do uzupełnienia ({record.issues.length})</summary><ul className="admin-publish-issues">{record.issues.map((issue, index) => <li key={`${issue.field}-${index}`}>{issue.message}</li>)}</ul></details>}{record.editorialStatus === 'draft' && <button type="button" className="admin-button" disabled={actionBusy || !!latest} onClick={() => void action('review')}><ChevronRight size={17} />Przejdź do sprawdzania</button>}{record.editorialStatus === 'in_review' && <button type="button" className="admin-button" disabled={actionBusy || !!latest || saveState !== 'saved' || !reviewKeys.every(key => record.checks[key]) || record.issues.length > 0} onClick={() => void action('approve')}><Check size={18} />Zaakceptuj wersję {record.revision}</button>}{record.editorialStatus === 'approved' && <button type="button" className="admin-button" disabled={actionBusy || !!latest || saveState !== 'saved' || record.publishedRevision === record.revision} onClick={() => void action('publish')}><CheckCircle2 size={18} />Opublikuj wersję {record.revision}</button>}</section>}<section className="admin-rail-section"><h2>Podgląd przepisu</h2>{recipe.image ? <MediaImage src={recipe.image} alt={photoDescription(recipe.imageAlt[locale])} width={310} height={195} sizes="(max-width: 520px) calc(100vw - 34px), (max-width: 1050px) calc((100vw - 110px) / 2), 260px" maximumWidth={640} className="admin-rail-preview" /> : <div className="admin-rail-preview" style={{ display: 'grid', placeItems: 'center' }}><Sprout size={44} strokeWidth={1.2} /></div>}<h3>{recipe.title[locale] || 'Bez tytułu'}</h3><div className="admin-actions admin-subtle"><Clock3 size={16} />{formatRecipeDuration(recipe.times.total, locale)} <Utensils size={15} />{recipe.baseServings} porcji</div><button type="button" className="admin-button is-secondary" disabled={actionBusy || !!latest || deleted} onClick={async () => { if (await flush()) setPreviewOpen(!previewOpen); }}><Eye size={18} />{previewOpen ? 'Zamknij podgląd' : 'Podgląd przepisu'}</button></section><section className="admin-rail-section"><h2>{deleted ? 'Kosz' : 'Wersja publiczna'}</h2>{deleted ? <><p className="admin-subtle">Usunięto {date(record.deletedAt!)}. Historia wersji i zdjęcia pozostają zachowane. Przywrócenie wymaga ponownego sprawdzenia przed publikacją.</p><button type="button" className="admin-button" disabled={actionBusy || !!latest} onClick={() => void action('restore_deleted')}><RotateCcw size={17} />Przywróć z kosza</button></> : <><p className="admin-review-check"><span className={`admin-tag ${record.publicationStatus === 'published' ? 'is-published' : ''}`}>{record.publicationStatus === 'published' ? `Publiczna · wersja ${record.publishedRevision}` : record.publicationStatus === 'unpublished' ? 'Wycofano z serwisu' : 'Jeszcze nie opublikowano'}</span></p><p className="admin-subtle">Zmiany szkicu nie zmieniają wersji publicznej.</p>{record.publicationStatus === 'published' && <button type="button" className="admin-button is-secondary" disabled={actionBusy || !!latest} onClick={() => void action('unpublish')}>Wycofaj z serwisu</button>}<button type="button" className="admin-button is-secondary" disabled={actionBusy || !!latest} onClick={() => void action('duplicate')}><Copy size={16} />Utwórz kopię szkicu</button>{readonly ? <button type="button" className="admin-button" disabled={actionBusy || !!latest} onClick={() => void action('restore')}><RotateCcw size={17} />Przywróć z archiwum</button> : <button type="button" className="admin-button is-subtle" disabled={actionBusy || !!latest || record.publicationStatus === 'published'} onClick={() => void action('archive')}>Przenieś do archiwum</button>}</>}</section></aside></div>
    {previewOpen && !deleted && <section className="admin-section" style={{ marginTop: 28 }}><h2>Podgląd zapisanej wersji {record.revision}</h2><p>Treść szkicu widoczna tylko w panelu redakcyjnym.</p><iframe className="admin-preview-frame" src={`/${locale}/preview/${encodeURIComponent(record.id)}?revision=${record.revision}`} title="Podgląd zapisanego przepisu" /></section>}
    {deleteOpen && <DeleteRecipeDialog title={recipe.title.pl || recipe.title.en} published={record.publicationStatus === 'published'} unsaved={fingerprint(content) !== fingerprint(record.content)} busy={actionBusy} error={deleteError} conflict={!!latest} onConfirm={() => void deleteRecipe()} onClose={() => { if (!busyRef.current) setDeleteOpen(false); }} onDownloadDraft={downloadDraft} />}
    <dialog ref={modalRef} className="admin-modal" onCancel={() => setMediaTarget(null)} onClose={() => setMediaTarget(null)}><h2>Wybierz zdjęcie z biblioteki</h2><p>Wybierz kadr zgodny z treścią przepisu.</p><div className="admin-media-grid" style={{ maxHeight: '55vh', overflowY: 'auto' }}>{mediaTarget?.type === 'ingredients' ? ingredientPhotoLabels.flatMap((labels, atlasIndex) => labels.map((label, index) => { const media: MediaTile = { src: `/images/ingredients-${atlasIndex + 1}.webp`, columns: 4, rows: 3, index, alt: { pl: label, en: ingredientPhotoEnglish[atlasIndex][index] } }; return <button type="button" key={`${atlasIndex}-${index}`} className="admin-media-choice" onClick={() => chooseMedia(media)}><RecipePhoto media={media} locale="pl" sizes="640px" className="ingredient-thumb" /><span>{label}</span></button>; })) : stepAtlases.flatMap(atlas => Array.from({ length: atlas.count }, (_, index) => { const media: MediaTile = { src: `/images/steps-${atlas.id}.webp`, columns: 2, rows: 3, index, aspectRatio: atlas.aspectRatio, alt: { pl: '', en: '' }, caption: { pl: '', en: '' } }; return <button type="button" key={`${atlas.id}-${index}`} className="admin-media-choice" onClick={() => chooseMedia(media)}><RecipePhoto media={{ ...media, alt: { pl: `${atlas.label}, kadr ${index + 1}`, en: '' } }} locale="pl" sizes="640px" className="ingredient-thumb" /><span>{atlas.label} · kadr {index + 1}</span></button>; }))}</div><div className="admin-actions"><button type="button" className="admin-button is-secondary" onClick={() => { modalRef.current?.close(); setMediaTarget(null); }}>Wróć do edycji</button></div></dialog>
  </>;
}
